using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using Nova;
class LiveTests {
    static int passed,failed;static StreamWriter log;
    static void Check(string n,Action a){try{a();passed++;Say("PASS "+n);}catch(Exception e){failed++;Say("FAIL "+n+": "+e.Message);}}
    static void Say(string s){Console.WriteLine(s);log.WriteLine(s);log.Flush();}
    static void Eq(float a,float b){if(Math.Abs(a-b)>0.01)throw new Exception(a+" != "+b);}
    static int Main(){Directory.CreateDirectory(".local");log=new StreamWriter(Path.Combine(".local","live-tests.txt"),false);try{using(var t=new Trainer(Process.GetProcessesByName("Greylock-Win64-Shipping").Single())){
        if(!t.Ready)throw new Exception(t.Status);var u=t.U;long p=t.Pawn,s=t.State,m=t.Movement;long w=t.CurrentWeapon(),proxyBefore=t.WeaponProxy(w);float mana=u.Mem.Float(s+0x420),adr=u.Mem.Float(s+0x388);int hp=u.Int(p,"MyHP"),shield=u.Int(p,"MyShield"),mag=u.Mem.Int(w+0x528),reserve=u.Mem.Int(t.AmmoPool(w)),bp=u.Int(w,"Ammunition Current"),proxyNative=proxyBefore==0?0:u.Mem.Int(proxyBefore+0x528),proxyBp=proxyBefore==0?0:u.Int(proxyBefore,"Ammunition Current");
        ObjectToken playerToken=u.Token(p),stateToken=u.Token(s),weaponToken=u.Token(w),proxyToken=proxyBefore==0?new ObjectToken():u.Token(proxyBefore);long poolBefore=t.AmmoPool(w);
        try{
            foreach(var setting in new[]{new[]{"manaRate","10","ManaRechargeRate"},new[]{"speed","2","CustomTimeDilation"},new[]{"jumpHeight","3000","JumpZVelocity"},new[]{"gravity","2","GravityScale"}}){string id=setting[0],field=setting[2];long owner=(id=="jumpHeight"||id=="gravity")?m:p;float original=u.Float(owner,field);Check(id+" apply, keep and restore",delegate{t.Apply(id,double.Parse(setting[1]));Thread.Sleep(150);t.Tick();Eq(u.Float(owner,field),float.Parse(setting[1]));t.ResetValue(id);Eq(u.Float(owner,field),original);});}
            Check("maximum grapple count and refill",delegate{int original=u.Int(p,"MaxGrappleShots"),baseCount=u.Int(p,"BaseGrappleShots");t.Apply("grappleCount",10);t.Action("refillGrapple");Eq(u.Int(p,"MaxGrappleShots"),10);Eq(u.Int(p,"GrappleShots"),10);t.ResetValue("grappleCount");Eq(u.Int(p,"MaxGrappleShots"),original);Eq(u.Int(p,"BaseGrappleShots"),baseCount);u.Mem.PutInt(u.Address(p,"GrappleShots","IntProperty"),original);});
            Check("jump count, unlimited, return to custom count and original",delegate{int original=u.Int(p,"JumpMaxCount");t.Apply("jumpCount",10);Eq(u.Int(p,"JumpMaxCount"),10);t.Toggle("jumpLock",true);Eq(u.Int(p,"JumpMaxCount"),1000000);t.Toggle("jumpLock",false);Eq(u.Int(p,"JumpMaxCount"),10);t.ResetValue("jumpCount");Eq(u.Int(p,"JumpMaxCount"),original);});
            Check("hook range and all rope lengths restore",delegate{string[] fields={"GrapMinRange","GrapMaxRange","GrappleHookLength","HaloGrappleHookLength"};float[] original=fields.Select(f=>u.Float(p,f)).ToArray();t.Toggle("grappleRange",true);Eq(u.Float(p,"GrapMaxRange"),10000000);Eq(u.Float(p,"GrappleHookLength"),10000000);t.Toggle("grappleRange",false);for(int i=0;i<fields.Length;i++)Eq(u.Float(p,fields[i]),original[i]);});
            Check("adrenaline set and persistent refill",delegate{t.Apply("adrenaline",35);Eq(u.Mem.Float(s+0x388),35);t.Toggle("adrenalineLock",true);u.Mem.PutFloat(s+0x388,0);t.Tick();Eq(u.Mem.Float(s+0x388),100);t.Toggle("adrenalineLock",false);});
            Check("low mana, refill, unlimited and no writes after disable",delegate{t.Apply("manaRate",0);t.Action("lowMana");Eq(u.Mem.Float(s+0x420),5);t.Action("refillMana");Eq(u.Mem.Float(s+0x420),100);t.Toggle("mana",true);u.Mem.PutFloat(s+0x420,1);t.Tick();Eq(u.Mem.Float(s+0x420),100);t.Toggle("mana",false);u.Mem.PutFloat(s+0x420,22);t.Tick();Eq(u.Mem.Float(s+0x420),22);t.ResetValue("manaRate");});
            Check("low health, heal, damage flag and flag restoration",delegate{Field f=u.Property(p,"bCanBeDamaged","BoolProperty");byte original=u.Mem.Byte(p+f.Offset);t.Action("lowHealth");Eq(u.Int(p,"MyShield"),1);t.Action("heal");Eq(u.Int(p,"MyShield"),u.Int(p,"MaxShield"));t.Toggle("health",true);Eq(u.Mem.Byte(p+f.Offset)&f.Mask,0);t.Toggle("health",false);Eq(u.Mem.Byte(p+f.Offset),original);});
            Check("set ammo synchronizes native, blueprint and first person proxy",delegate{t.Apply("ammo",123);Eq(u.Mem.Int(w+0x528),123);Eq(u.Int(w,"Ammunition Current"),123);long proxy=t.WeaponProxy(w);if(proxy==0)throw new Exception("Missing first person weapon");Eq(u.Mem.Int(proxy+0x528),123);Eq(u.Int(proxy,"Ammunition Current"),123);Eq(u.Mem.Int(t.AmmoPool(w)),123);});
            Check("unlimited ammo and stop refilling",delegate{t.Toggle("ammoLock",true);u.Mem.PutInt(w+0x528,1);t.Tick();Eq(u.Mem.Int(w+0x528),9999);t.Toggle("ammoLock",false);u.Mem.PutInt(w+0x528,7);t.Tick();Eq(u.Mem.Int(w+0x528),7);});
            Check("unlimited grapple replenishes real player",delegate{t.Toggle("grappleLock",true);u.Mem.PutInt(u.Address(p,"GrappleShots","IntProperty"),0);t.Tick();Eq(u.Int(p,"GrappleShots"),u.Int(p,"MaxGrappleShots"));t.Toggle("grappleLock",false);});
            Check("reset all settings clears patches",delegate{t.Apply("speed",1.5);t.Apply("gravity",1);t.Toggle("grappleRange",true);t.ResetAll();Eq(t.Patches.Count,0);Eq(t.Values.Count,0);Eq(t.Toggles.Count,0);});
        }finally{t.ResetAll();if(u.Identity(s,stateToken.Index,stateToken.Serial)){u.Mem.PutFloat(s+0x420,mana);u.Mem.PutFloat(s+0x388,adr);}if(u.Identity(p,playerToken.Index,playerToken.Serial)){u.Mem.PutInt(u.Address(p,"MyHP","IntProperty"),hp);u.Mem.PutInt(u.Address(p,"MyShield","IntProperty"),shield);}if(u.Identity(w,weaponToken.Index,weaponToken.Serial)){u.Mem.PutInt(w+0x528,mag);u.Mem.PutInt(u.Address(w,"Ammunition Current","IntProperty"),bp);if(u.Identity(s,stateToken.Index,stateToken.Serial)&&t.AmmoPool(w)==poolBefore)u.Mem.PutInt(poolBefore,reserve);}if(proxyBefore!=0&&u.Identity(proxyBefore,proxyToken.Index,proxyToken.Serial)){u.Mem.PutInt(proxyBefore+0x528,proxyNative);u.Mem.PutInt(u.Address(proxyBefore,"Ammunition Current","IntProperty"),proxyBp);}}
    }}catch(Exception e){failed++;Say("FAIL fatal: "+e);}Say(passed+" passed, "+failed+" failed");log.Dispose();return failed==0?0:1;}
}
